import { DEX_ORDER, isCorrectGuess, normalizeName, searchPokemonNames, speciesOf } from './pokedex';

// Localized names live in a separate JSON file (src/data/pokemon-names-i18n.json, generated by
// scripts/generate-pokemon-names.mjs) that is only downloaded once a non-English language is
// needed, so English-only players never pay for it.

export const NAME_LANGUAGES = [
  { code: 'en', label: 'English' },
  { code: 'ja', label: '日本語 (katakana)' },
  { code: 'ja-roomaji', label: 'Japanese (rōmaji)' },
  { code: 'fr', label: 'Français' },
  { code: 'de', label: 'Deutsch' },
  { code: 'es', label: 'Español' },
  { code: 'it', label: 'Italiano' },
  { code: 'ko', label: '한국어' },
  { code: 'zh-Hans', label: '简体中文' },
  { code: 'zh-Hant', label: '繁體中文' },
] as const;
export type NameLanguage = (typeof NAME_LANGUAGES)[number]['code'];

export interface NameData {
  languages: string[];
  /** names[speciesId - 1][languageIndex]; "" means "same as the English name". */
  names: string[][];
}

let loaded: NameData | null = null;
let loading: Promise<NameData> | null = null;

/** Downloads the localized names once; later calls share the result. */
export function loadNameData(): Promise<NameData> {
  loading ??= import('@/data/pokemon-names-i18n.json').then(
    (m) => (loaded = m.default as NameData),
    (err) => {
      loading = null; // allow a retry after a network failure
      throw err;
    },
  );
  return loading;
}

/** The names if they have already been downloaded, otherwise null. */
export function getLoadedNameData(): NameData | null {
  return loaded;
}

const englishName = new Map(DEX_ORDER.map((e) => [e.id, e.name]));

/**
 * A Pokémon's name in one language, or null when it has none of its own (English, or a name
 * identical to the English one). A form reuses its English label with the species name swapped
 * for the localized one ("Mega Charizard X" -> "Mega リザードン X"), so forms stay distinct from
 * their base species in every language.
 */
export function localizedName(id: number, lang: string, data: NameData): string | null {
  const col = data.languages.indexOf(lang);
  const sid = speciesOf(id);
  const own = col < 0 ? '' : data.names[sid - 1]?.[col];
  if (!own) return null;
  if (sid === id) return own;
  const species = englishName.get(sid);
  const label = englishName.get(id);
  return species && label?.includes(species) ? label.replace(species, own) : null;
}

/** The name to show for a Pokémon in a language, falling back to English. */
export function displayName(id: number, english: string, lang: NameLanguage, data: NameData | null): string {
  return (data && lang !== 'en' && localizedName(id, lang, data)) || english;
}

/** Judges a guess: the English name or the name in any supported language is correct. */
export function isCorrectGuessAnyLanguage(guess: string, pokemon: { id: number; name: string }, data: NameData | null): boolean {
  if (isCorrectGuess(guess, pokemon.name)) return true;
  if (!data) return false;
  const g = normalizeName(guess);
  return (
    g.length > 0 &&
    data.languages.some((lang) => {
      const n = localizedName(pokemon.id, lang, data);
      return n !== null && normalizeName(n) === g;
    })
  );
}

export interface NameSuggestion {
  /** What a tap submits. */
  text: string;
  /** The English name, shown alongside a localized suggestion. */
  english?: string;
}

interface Entry extends NameSuggestion {
  key: string;
  wordKeys: string[];
}

const entryCache = new Map<string, Entry[]>();

function localizedEntries(lang: NameLanguage, data: NameData): Entry[] {
  const hit = entryCache.get(lang);
  if (hit) return hit;
  const seen = new Set<string>();
  const entries: Entry[] = [];
  for (const { id, name } of DEX_ORDER) {
    const text = localizedName(id, lang, data);
    if (!text || seen.has(text)) continue;
    seen.add(text);
    entries.push({
      text,
      english: name,
      key: normalizeName(text),
      wordKeys: text.split(/[\s-]+/).map(normalizeName).filter(Boolean),
    });
  }
  entryCache.set(lang, entries);
  return entries;
}

/**
 * Autocomplete across English and the chosen language: English names first (as in
 * searchPokemonNames), then names in the chosen language with the English name alongside. Up to
 * half the list is kept for the chosen language so neither side crowds the other out.
 */
export function searchNames(query: string, lang: NameLanguage, data: NameData | null, limit = 8): NameSuggestion[] {
  const english: NameSuggestion[] = searchPokemonNames(query, limit).map((text) => ({ text }));
  const q = normalizeName(query);
  if (lang === 'en' || !data || !q) return english;
  const starts: NameSuggestion[] = [];
  const wordStarts: NameSuggestion[] = [];
  for (const e of localizedEntries(lang, data)) {
    if (e.key.startsWith(q)) starts.push({ text: e.text, english: e.english });
    else if (e.wordKeys.some((w) => w.startsWith(q))) wordStarts.push({ text: e.text, english: e.english });
    if (starts.length >= limit) break;
  }
  const local = [...starts, ...wordStarts].slice(0, limit);
  const keepEnglish = limit - Math.min(local.length, Math.floor(limit / 2));
  return [...english.slice(0, keepEnglish), ...local].slice(0, limit);
}
